"""Complete dressed vegetables and companion vinaigrettes."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def mix(extra=()):return ['In a small bowl, whisk {{vinegar}}, {{salt}} and {{pepper}}'+(' with '+', '.join(tk(k) for k in extra) if extra else '')+' until the salt is dissolved.','Gradually whisk in {{oil}} until evenly blended. Toss with the salad immediately before serving.',STORE]

def water(a,k='water'):return I(k,a,'ml','drinking water','Use enough drinking water to keep the vegetables covered while boiling.')
def shallots(a=120):return I('shallots',a,'g','small tender shallots, peeled and trimmed','Use the same weight of trimmed young green onions, including tender white and pale-green parts, for a different flavor.')
def creoleitems():return [shallots(),vinegar(30),oil(75),parsley(6),salt(.25),pepper(.125)]
def creolesteps():return ['Chop {{shallots}} very finely. Whisk {{vinegar}}, {{salt}} and {{pepper}} in a bowl until the salt dissolves.','Gradually whisk in {{oil}}, then stir in the chopped shallots and {{parsley}}. The result is a chunky sauce, not a smooth dressing.']
CREOLE='The original scan really says twelve shallots. This adaptation uses 120 g small tender shallots, an explicit modern weight rather than a claim that twelve modern large bulbs weigh that amount. The source vinegar, oil and parsley proportions are retained. The cold Ravigote reference is expanded as fine chopping and mixing; no unstated extra herbs are added.'
r=add(151,'Creole Shallot Vinaigrette',12,15,'Finely chopped shallots and parsley make a chunky, sharp vinaigrette for vegetables, cold meat or fish.',creoleitems(),creolesteps()+['Spoon a small portion over each serving, stirring so the shallots and oil are distributed evenly.',STORE],CREOLE+' Yield is approximately 230–250 ml, depending on the chopped shallots.')

r=add(145,'Guatemalan Parsley and Mustard Vinaigrette',6,15,'Ground parsley and mustard powder make a pungent green dressing with oil and vinegar.',[I('parsley',10,'g','fresh parsley leaves and tender stems','Use the same weight of cilantro for a different flavor.'),vinegar(15),I('mustard',2,'tsp','dry mustard powder','Use 10 ml prepared Dijon mustard for a milder, tangier adaptation.'),oil(45),salt(.25)],['Wash {{parsley}}, dry well and grind to a paste in a mortar, or chop very finely and crush with the flat side of a knife.','Mix {{mustard}} and {{vinegar}} in a small bowl until smooth. Stand for 5 minutes to hydrate the mustard powder.','Stir in the parsley paste and {{salt}}, then gradually whisk in {{oil}}. Serve in small amounts alongside cooked meat or vegetables.',STORE],'The source gives two undefined spoonfuls mustard powder and three spoonfuls oil, with no parsley or vinegar quantity. The modern choice is two teaspoons powder, three tablespoons oil, 15 ml vinegar and 10 g parsley. These are supplied quantities, not recovered historical spoon conversions. The dressing is intentionally pungent.')

r=add(143,'Chilled Asparagus with Mustard Vinaigrette',4,150,'Tender asparagus is dressed while warm with mustard vinaigrette, then chilled until the flavors mingle.',[I('asparagus',500,'g','fresh asparagus, tough bases snapped off','Use the same weight of trimmed green beans; boil until tender, usually 6–10 minutes.'),water(1500),I('boilsalt',5,'g','fine salt for the cooking water','Reduce or omit.'),oil(45),vinegar(15),I('mustard',1,'tsp','prepared Dijon mustard','Use the same amount of prepared yellow mustard.'),salt(.25),I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild dressing.'),I('sugar',.25,'tsp','granulated sugar','Use the same amount of caster sugar.')],['Bring {{water}} and {{boilsalt}} to a boil in a wide pan. Add {{asparagus}} and simmer for 3–7 minutes, depending on thickness, until tender when pierced but still intact. Drain well.','While the asparagus cooks, whisk {{vinegar}}, {{mustard}}, {{salt}}, {{cayenne}} and {{sugar}} until smooth, then gradually whisk in {{oil}}.','Put the warm drained asparagus in a shallow dish and spoon the dressing over it. Turn gently to coat. Let steam escape briefly, then cover and refrigerate promptly, within 2 hours of cooking.','Chill for about 2 hours at 4°C (40°F) or colder before serving. Turn gently once while chilling. Serve cold with the dressing from the dish. Refrigerate leftovers and use within 3 days.'],'The missing asparagus weight and complete boiling method are supplied. The source three tablespoons oil, tablespoon vinegar and teaspoon mustard are retained. One saltspoon sugar becomes a modern quarter teaspoon. The warm dressing and cold serving sequence is retained, with prompt refrigeration replacing an unspecified room-temperature wait. Total time includes chilling.');r['category']='Side dishes'

r=add(148,'Artichokes with Cooked-Yolk Shallot Vinaigrette',6,70,'Tender whole artichokes are served with a small bowl of thick olive-oil, shallot and cooked-yolk vinaigrette.',[I('artichokes',6,'','small young globe artichokes, about 150 g each','Use six similar small globe artichokes; larger ones need more cooking time and more sauce.'),water(3000),I('boilsalt',10,'g','fine salt for the artichoke water','Reduce or omit.'),I('egg',1,'','large egg','Use a large pasteurized shell egg if preferred; cook it fully.'),water(750,'eggwater'),vinegar(10),shallots(15),oil(45),salt(.25),pepper(.125)],['Trim the stems of {{artichokes}} so they stand upright. Pull away tough outer leaves, cut about 2 cm off the top and snip sharp points from remaining outer leaves. Rinse between the leaves.','Bring {{water}} and {{boilsalt}} to a boil in a deep pot. Add the artichokes, adding more hot water if needed to cover them. Cover and simmer for 25–45 minutes, or until an outer leaf pulls out easily and the base is tender when pierced. Lift out and drain upside down. Large or less tender artichokes may need longer.','While the artichokes cook, put {{egg}} in a small pan with {{eggwater}}, adding more water if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open. The yolk must be firm throughout. Reserve the cooked white in the refrigerator for another dish.','Mash the cooked yolk with {{vinegar}}, {{salt}} and {{pepper}} until smooth. Chop {{shallots}} very finely and stir in, then gradually whisk in {{oil}}.','Serve the warm artichokes with the sauce on the side. Pull off one leaf at a time, dip the fleshy base in sauce and scrape off the soft flesh with your teeth; discard the fibrous leaf. When the inner leaves are reached, lift them out and scrape away every part of the fuzzy choke with a spoon. Eat the tender heart beneath it, not the choke.','Refrigerate leftover artichokes and dressing separately within 2 hours at 4°C (40°F) or colder, and use within 3 days.'],'The original page conflicts with itself: the list gives butter and two tablespoons vinegar, while the method gives olive oil and two teaspoons vinegar. This adaptation explicitly follows the method: 45 ml olive oil and 10 ml vinegar. Six young artichokes come from the full original recipe; 15 g shallot and seasonings are supplied. The full boiling cross-reference, cooked egg method and choke removal are included.');r['category']='Side dishes'

r=add(149,'Chilled Canned Asparagus with Creole Vinaigrette',4,90,'Ready-cooked asparagus is gently warmed, drained and chilled, then served with a generous chunky shallot-and-parsley vinaigrette.',[I('asparagus',400,'g','drained canned asparagus spears','Use the same drained weight of jarred cooked asparagus.'),water(250)]+creoleitems(),['Put {{asparagus}} in a wide pan with {{water}}. Warm gently for 2–3 minutes until heated through without boiling vigorously; the canned asparagus is already cooked. Drain well and spread in a shallow dish.','Let excess steam escape briefly, then cover and refrigerate promptly. Chill for about 1 hour at 4°C (40°F) or colder.']+creolesteps()+['Serve the cold asparagus with the vinaigrette in a separate bowl, allowing diners to spoon it over the spears. This batch makes approximately 230–250 ml sauce, a generous quantity for four portions.','Refrigerate leftovers within 2 hours at 4°C (40°F) or colder and use within 3 days.'],CREOLE+' The original boiling cross-reference explicitly says canned asparagus is already cooked and only needs heating. A modern drained can weight of 400 g is supplied. The complete sauce batch approximates the source half-pint quantity; it is served separately because it is generous. Total time includes chilling.');r['category']='Side dishes'

r=add(150,'Green Beans with Creole Vinaigrette',6,35,'Boiled green beans are dressed with chopped shallots and parsley, then garnished with lemon slices and gherkin fans.',[I('beans',750,'g','fresh green beans, stalk ends trimmed','Use the same weight of yellow wax beans; cook until tender.'),water(2500),I('boilsalt',8,'g','fine salt for the bean water','Reduce or omit.')]+creoleitems()+[I('lemon',1,'','small lemon, washed','Use one small lime for a different flavor.'),I('garnishparsley',1,'tbsp','fresh parsley, finely chopped for garnish','Use the same amount of chopped chives.'),I('gherkins',6,'','small pickled gherkins, drained','Use six cornichons.')],['Bring {{water}} and {{boilsalt}} to a boil in a large pot. Add {{beans}}, returning to a gentle boil, and cook for 6–10 minutes until tender. Drain thoroughly.']+creolesteps()+['Toss the warm drained beans with the vinaigrette and arrange in a shallow serving dish.','Cut {{lemon}} into six thin slices, removing any seeds, and cut any remaining lemon into wedges. Put {{garnishparsley}} on a small plate and press one edge of each lemon slice into it. Make several lengthwise cuts in {{gherkins}}, keeping one end joined, then spread the cuts gently into fans.','Arrange the lemon and gherkins around the beans and serve. Refrigerate leftovers within 2 hours at 4°C (40°F) or colder and use within 3 days.'],CREOLE+' Two source quarts of beans become an explicitly estimated modern 750 g; this is not a verified volume-to-weight conversion. The butter-sauce reference supplies the boiling method only: butter is not added to this vinaigrette dish. The lemon, parsley and gherkin garnish is retained with supplied quantities.');r['category']='Side dishes'

r=add(197,'Tomato and Lettuce Salad with Sweet French Dressing',6,15,'Thinly sliced ripe tomatoes rest on lettuce and are dressed just before serving with a lightly sweet paprika vinaigrette.',[I('tomatoes',900,'g','firm ripe red tomatoes, about six medium','Use the same weight of mixed ripe tomatoes; slice larger ones and halve small ones.'),I('lettuce',100,'g','lettuce leaves','Use the same weight of romaine leaves.'),salt(),pepper(),I('sugar',1,'tsp','granulated sugar','Use the same amount of caster sugar.'),I('paprika',.125,'tsp','sweet paprika','Use the same amount of smoked paprika for a different flavor.'),vinegar(30),oil(60)],['Wash {{tomatoes}} and pat dry. Remove their cores and slice thinly with a sharp knife. Wash {{lettuce}}, dry well and line a serving bowl or platter with the leaves. Arrange the tomatoes over them.','Whisk {{vinegar}}, {{salt}}, {{pepper}}, {{sugar}} and {{paprika}} in a small bowl until the salt and sugar dissolve. Gradually whisk in {{oil}} until blended.','Just before serving, spoon the dressing over the tomatoes and lettuce. Serve immediately so the lettuce stays crisp. Refrigerate any leftovers within 2 hours at 4°C (40°F) or colder and use within 1 day; the salad will soften.'],'The full French dressing component comes from the same Greenbaum book: four tablespoons oil, two vinegar, a teaspoon sugar, half-teaspoon salt, quarter-teaspoon pepper and a dash of paprika. Tomato and lettuce weights are supplied. Salt and pepper are included once in the dressing instead of adding a second unmeasured seasoning to the tomatoes.');r['category']='Salads'

assert len(newids)==7,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full vegetable and condiment methods supplied; original-page inconsistencies disclosed and complete sauces included','repair-batch-019.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=0,totalOverrides=len(records),totalAliases=len(aliases))))

